@startuml

class House {
  + Address : string
  + BuildingMaterial : string
}

abstract class Basement {
  + Size : double
  + Name : string
}

class EarthBasement extends Basement {
  + HumidityLevel : double
}

class ConcreteBasement extends Basement {
}

class SemiDetachedHouse extends House {
  + HasOwnGarden : boolean
  + WindowsCount : int
}

class Carport {
  + IsDoubleCarport : boolean
  + HasFlatRoof : boolean
}

class Garage {
  + HasAutomaticGarageDoor : boolean
}

class Company {
  + Name : string
  + Address : string
}

class JobLog {
  + Hours : double
  + Price : double
}

House "0..1" -- "0..1" Basement
House "1" -- "*" Company
House "1" -- "*" JobLog
Company "1" -- "*" JobLog
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "0..1" Garage

@enduml

